package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.lang.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_append_TriageGen0Test {

    @Test
    public void testAppend_ValidHtml_AppendsChildren() {
        Element parent = new Element("div", "");
        String html = "<p>Hello</p><span>World</span>";

        Element result = parent.append(html);

        // Check return type (fluent API)
        Assert.assertEquals(parent, result);

        // Check if children were added
        Assert.assertEquals(2, parent.children().size());
        Assert.assertEquals("p", parent.child(0).tagName());
        Assert.assertEquals("span", parent.child(1).tagName());
        Assert.assertEquals("Hello", parent.child(0).text());
        Assert.assertEquals("World", parent.child(1).text());
    }

    @Test
    public void testAppend_EmptyHtml_DoesNothing() {
        Element parent = new Element("div", "");
        String html = "";

        parent.append(html);

        Assert.assertTrue(parent.children().isEmpty());
    }

    @Test
    public void testAppend_TextOnly_AppendsTextNode() {
        Element parent = new Element("div", "");
        String html = "Just text";

        parent.append(html);

        // When parsing a fragment with just text, jsoup creates a TextNode
        Assert.assertEquals(1, parent.childNodes().size());
        Assert.assertEquals("Just text", parent.text());
    }

    @Test(expected = NullPointerException.class)
    public void testAppend_NullHtml_ThrowsException() {
        Element parent = new Element("div", "");
        parent.append(null);
    }

    @Test
    public void testAppend_ComplexHtml_MaintainsStructure() {
        Element parent = new Element("div", "");
        String html = "<div><ul class='list'><li>1</li><li>2</li></ul></div><p>Footer</p>";

        parent.append(html);

        // The parser wraps the fragment in a body, so the top level elements are div and p
        Assert.assertEquals(2, parent.children().size());
        Element div = parent.child(0);
        Assert.assertEquals("div", div.tagName());
        Assert.assertEquals(1, div.children().size());
        Assert.assertEquals("ul", div.child(0).tagName());
        Assert.assertEquals("list", div.child(0).child(0).className());

        Element p = parent.child(1);
        Assert.assertEquals("p", p.tagName());
        Assert.assertEquals("Footer", p.text());
    }

    @Test
    public void testAppend_FragmentWithMixedNodes() {
        Element parent = new Element("div", "");
        // Mixing text nodes and elements
        String html = "Text<br>More Text";

        parent.append(html);

        // Text, Br, Text
        Assert.assertEquals(3, parent.childNodes().size());
        Assert.assertEquals("Text", parent.child(0).toString()); // Note: child(int) returns Element, but childNodes() returns Node
        // Using childNodes to verify exact count
        Assert.assertEquals("Text", parent.childNodes().get(0).toString());
        Assert.assertEquals("br", parent.childNodes().get(1).nodeName());
        Assert.assertEquals("More Text", parent.childNodes().get(2).toString());
    }
}
